-- Reading the catalog index: one file, parsed, never run.
--
-- What a catalog *is* is a Lua table generated by this repository
-- (`scripts/generate-catalog.lua` and the bundler both write it) listing every
-- package with its version, description and the exact files it is made of.
-- Searching the panel is a lookup in this table; it installs nothing and
-- downloads nothing else.
--
-- It is read as *text* and pattern-matched, never `dofile`d. The file arrives
-- over the network, and `dofile` here would be executing whatever the network
-- handed back, inside the editor, before anything in it had been looked at.
--
-- Nothing in this module downloads. The catalog is no longer fetched as a file:
-- the registry is a persistent sparse clone (`cdinx/manager/registry.lua` plus
-- `manager/transport.lua`), and "refresh the catalog" means moving that clone.
-- What is left here is the reader for the one file that clone checks out, and
-- nothing else -- a second fetch mechanism beside the clone is the thing every
-- new caller reaches for by accident.
--
-- Deleted, with the downloader that was the only reason for them:
-- `Fetch.start`, `Fetch.poll`, `Fetch.sync`, `Fetch.find_downloader`, the curl /
-- wget / PowerShell command builders, the detached-download job, `mkdir_p`,
-- `strip_trailing`, `quote`, `quote_url`, `write_all`, `last_line`, `capture`,
-- `probe`, `remove`, `CATALOG_ROOTS`, `safe_relpath`, `Fetch.download` and
-- `Fetch.discard`. The `Registry.set_syncer` seam that chose between them went
-- with it; `Manager.set_registry_syncer` remains only as a deprecation shim.
local Fetch = {}

-- The file the catalog is read from. One, since Phase 9 removed `X/` and with it
-- the older of the two generated indexes this used to prefer between.
local CATALOG_FILES = { "registry/generated/catalog.lua" }

--- The largest catalog that is still a catalog.
---
--- A list of short records, one per package. Past this it is not one, and
--- refusing before parsing is what keeps a hostile "catalog" from costing
--- anything to reject.
local MAX_BYTES = 4 * 1024 * 1024

--- Reads a catalog index and returns its table, or nil plus why not.
---
--- What is looked for is only the shape of a catalog -- entries that are
--- tables, a `files` list each -- because the point is to refuse a file that is
--- not one before it is stored, not to trust anything inside it.
--- @param path string
--- @return table|nil data
--- @return string|nil err
function Fetch.read_catalog(path)
  local handle = io.open(path, "rb")
  if not handle then return nil, "cannot open " .. tostring(path) end
  local text = handle:read("*a")
  handle:close()

  if type(text) ~= "string" or text == "" then
    return nil, "the catalog file is empty"
  end
  if #text > MAX_BYTES then
    return nil, string.format("the catalog file is %d bytes; the limit is %d",
      #text, MAX_BYTES)
  end

  -- `["name"] = {` at the start of a line, one per entry, is what makes it a
  -- catalog: the value is never read, only counted.
  local entries = 0
  for _ in text:gmatch('\n%s*%["[^"]+"%]%s*=%s*{') do
    entries = entries + 1
  end
  if entries == 0 then
    return nil, "the catalog file lists no entries"
  end

  -- The body runs to the entry's own closing brace: a line with exactly the
  -- entry's four-space indent followed by `}`. The old terminator -- any line
  -- whose first non-space character is `}` -- matched the *files* table's close
  -- first (`files` is always the last field, at six spaces), so every entry came
  -- back with an empty file list and anything that needed `files[1]` found
  -- nothing. Both generators write entries at four spaces, so the indent is
  -- load-bearing and said so here rather than assumed quietly.
  local found = {}
  for name, body in text:gmatch('\n%s*%["([^"]+)"%]%s*=%s*{(.-)\n    }') do
    local entry = { name = name }
    for key, value in body:gmatch('([%a_][%w_]*)%s*=%s*"([^"]*)"') do
      entry[key] = value
    end
    -- Only the strings inside `files = { ... }`. Every other quoted string in the
    -- body is a scalar field, and collecting those too would hand the reader a
    -- file list made of the package's own name and category.
    entry.files = {}
    local files_block = body:match('files%s*=%s*{(.-)}')
    if files_block then
      for file in files_block:gmatch('"([%w%-%._/]+)"') do
        entry.files[#entry.files + 1] = file
      end
    end
    entry.name = nil
    found[name] = entry
  end

  return { plugins = found }
end

Fetch.CATALOG_FILES = CATALOG_FILES

return Fetch
